<?php if (!defined('ABSPATH')) exit; $cat=Psc_Messages::get_categories()[$message->categorie]; ?>
<div class="wrap psc-messages-admin"><a href="<?php echo esc_url(admin_url('admin.php?page=psc_messages')); ?>">← <?php esc_html_e('Tous les messages', 'periscolaire-registration'); ?></a><p><span class="psc-cat" style="--cat-bg:<?php echo esc_attr($cat['bg']); ?>;--cat-fg:<?php echo esc_attr($cat['fg']); ?>"><?php echo esc_html($cat['label']); ?></span> <?php printf(esc_html__('Envoyé le %1$s à %2$s · par %3$s', 'periscolaire-registration'), esc_html(date_i18n('d/m/Y',strtotime($message->date_envoi))), esc_html(date_i18n('H\hi',strtotime($message->date_envoi))), esc_html($author ? $author->display_name : '—')); ?></p><h1><?php echo esc_html($message->titre); ?></h1><div class="psc-message-rendered"><?php echo wp_kses($message->corps,Psc_Messages::allowed_html()); ?></div>
<div class="psc-message-tiles"><div><small>Destinataires</small><strong><?php echo $stats['total']; ?></strong></div><div><small>Ont vu</small><strong><?php echo $stats['vus']; ?> · <?php echo $stats['taux']; ?> %</strong></div><div><small>Non lu</small><strong class="psc-message-danger"><?php echo $stats['non_lus']; ?></strong></div><div><small>1re lecture</small><strong><?php $d=$stats['delai_median_minutes']; echo $d===null?'—':($d<60?$d.' min':floor($d/60).' h '.($d%60)); ?></strong></div></div>
<p><?php foreach(array('tous'=>'Tous','vus'=>'A vu','non_lus'=>'Non lu') as $key=>$label): ?><a class="button<?php echo $filter===$key?' button-primary':''; ?>" href="<?php echo esc_url(add_query_arg(array('page'=>'psc_message_stats','id'=>$message->id,'filter'=>$key),admin_url('admin.php'))); ?>"><?php echo esc_html($label); ?></a> <?php endforeach; ?></p>
<div class="psc-stats-actions"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="psc_resend_message"><input type="hidden" name="id" value="<?php echo (int)$message->id; ?>"><?php wp_nonce_field('psc_resend_message'); ?><button class="button"><?php printf(esc_html__('Relancer les %d non-lecteurs','periscolaire-registration'),$stats['non_lus']); ?></button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="psc_export_message"><input type="hidden" name="id" value="<?php echo (int)$message->id; ?>"><?php wp_nonce_field('psc_export_message'); ?><button class="button"><?php esc_html_e('Exporter CSV','periscolaire-registration'); ?></button></form></div>
<table class="wp-list-table widefat fixed striped"><thead><tr><th>Famille</th><th>Enfants</th><th>Statut</th><th>Vu le</th></tr></thead><tbody><?php foreach($recipients as $r): ?><tr><td><strong><?php echo esc_html(trim($r->prenom.' '.$r->nom)); ?></strong><br><small><?php echo esc_html($r->email); ?></small></td><td><?php echo esc_html(Psc_Messages_Admin::children_label($r->family_id)); ?></td><td><span class="psc-status <?php echo $r->vu_le?'psc-status-vus':'psc-status-non-lus'; ?>"><?php echo $r->vu_le?'A vu':'Non lu'; ?></span></td><td><?php if($r->vu_le): echo esc_html(date_i18n('d/m/Y H:i',strtotime($r->vu_le))); ?><br><small><?php echo esc_html($r->vu_canal); ?></small><?php else: ?>—<br><small><?php echo $r->email_statut==='envoye'?'E-mail délivré':($r->email_statut==='echec'?esc_html($r->email_erreur ?: 'Échec de l’envoi'):'—'); ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
